#!/usr/bin/env python3
"""Search small cores for Z == 0 using the reference brute force."""
import json
import random
import sys
sys.path.insert(0, 'tmp')
import ref

def core_and_final(doc):
    ixps, rib, priors, declared, order_pairs, queries = ref.validate(doc)
    agg = {}
    for p, c in rib:
        q = ref.norm(p, ixps)
        if len(q) < 2 or len(set(q)) != len(q):
            continue
        t = tuple(q)
        agg[t] = agg.get(t, 0) + c
    final, rounds, links = ref.peel_ref(agg)
    core = sorted(k for k in links if k not in rounds)
    return final, core

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
found = 0
seen = 0
minZ = None
for it in range(300000):
    n = rng.randint(3, 6)
    asns = list(range(1, n + 1))
    rib = []
    mode = rng.randrange(4)
    if mode == 0:
        # cyclic rotations
        base = asns[:]
        rng.shuffle(base)
        for k in range(n):
            if rng.random() < 0.7:
                rib.append({'path': base[k:] + base[:k], 'count': rng.randint(1, 3)})
    elif mode == 1:
        # random short paths
        for _ in range(rng.randint(1, 6)):
            p = [rng.choice(asns) for _ in range(rng.randint(3, 4))]
            rib.append({'path': p, 'count': rng.randint(1, 3)})
    elif mode == 2:
        # length-4 paths with interior links (two-var contexts)
        for _ in range(rng.randint(1, 6)):
            p = [rng.choice(asns) for _ in range(4)]
            rib.append({'path': p, 'count': rng.randint(1, 3)})
    else:
        # mix of rotations and random
        base = asns[:]
        rng.shuffle(base)
        for k in range(n):
            rib.append({'path': base[k:] + base[:k], 'count': rng.randint(1, 3)})
        for _ in range(rng.randint(1, 4)):
            p = [rng.choice(asns) for _ in range(rng.randint(3, 5))]
            rib.append({'path': p, 'count': rng.randint(1, 3)})
    doc = {'version': 1, 'ixps': [], 'rib': rib, 'priors': [], 'declared': [],
           'order': [], 'queries': []}
    try:
        final, core = core_and_final(doc)
    except ref.Invalid:
        continue
    if len(core) < 2 or len(core) > 7:
        continue
    seen += 1
    Z, margs = ref.infer_bruteforce(final, core)
    if minZ is None or (Z > 0 and Z < minZ):
        minZ = Z
    if Z == 0:
        print('ZERO PARTITION FOUND')
        print(json.dumps(doc))
        found += 1
        if found >= 3:
            break
print('search done, cores tested:', seen, 'zeros:', found, 'minZ:', minZ)
